"""Longest Word in Dictionary — sort, then grow only from buildable prefixes.

Sorting alphabetically means a word's prefix is always seen first, so a set of
valid words is enough; the length/lexicographic tie-break falls out of the sort.

Time: O(n log n * L)   Space: O(n * L)
"""
from typing import List


class Solution:
    def longestWord(self, words: List[str]) -> str:
        words.sort()
        buildable = {""}
        best = ""
        for word in words:
            if word[:-1] in buildable:
                buildable.add(word)
                if len(word) > len(best):
                    best = word
        return best
